window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ae1931a6a16797e5"]={"versions": [{"id": "FIG-ae1931a6a16797e5", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Mapping- und Strukturdiagramm der AUTOSAR Classic Platform (Software Component Template). Das Schaubild visualisiert das Bitfield-Mapping innerhalb eines <code>NvBlockSwComponentType</code> zwischen einzelnen Bits eines nichtflüchtigen Speicherblocks (<code>NvBlockDescriptor.ramBlock</code>) und den Datenelementen eines Ports (<code>RPortPrototype</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Hauptentitäten:</p>\n<ul class=\"fig-list\">\n<li><strong>NvBlockDescriptor</strong>: Repräsentiert den NV-Block und enthält <code>NvBlockDescriptor.ramBlock</code> als Byte- bzw. Bitfeldstruktur mit 8 visualisierten Bit-Positionen, von denen Bit 1 (Maske 0x02) und Bit 4 (Maske 0x10) blau hervorgehoben sind.</li>\n<li><strong>RPortPrototype</strong>: Repräsentiert die Port-Schnittstelle mit zwei separaten Datenelementen vom Typ <code>Boolean</code>, bei denen jeweils das niederwertigste Bit (LSB) hervorgehoben ist.</li>\n<li><strong>NvBlockDataMapping</strong>: Zwei Mapping-Instanzen mit folgenden Attributbelegungen:</li>\n<li>Erstes Mapping: <code>bitfieldTextTableMaskNvBlockDescriptor = 0x10</code>, <code>bitfieldTextTableMaskPortPrototype = 0x01</code> (verbindet Bit 4 des RAM-Blocks mit dem zweiten Boolean-Datenelement).</li>\n<li>Zweites Mapping: <code>bitfieldTextTableMaskNvBlockDescriptor = 0x02</code>, <code>bitfieldTextTableMaskPortPrototype = 0x01</code> (verbindet Bit 1 des RAM-Blocks mit dem ersten Boolean-Datenelement).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Abbildungsmodell ohne sequenziellen Laufzeitablauf. Gerichtete Pfeile definieren die Zuordnungsvorschrift:</p>\n<ul class=\"fig-list\">\n<li>Der Pfeil von der oberen <code>NvBlockDataMapping</code>-Instanz zeigt auf Bit 1 des <code>ramBlock</code> sowie auf das LSB des oberen <code>Boolean</code>-Elements des <code>RPortPrototype</code>.</li>\n<li>Der Pfeil von der unteren <code>NvBlockDataMapping</code>-Instanz zeigt auf Bit 4 des <code>ramBlock</code> sowie auf das LSB des unteren <code>Boolean</code>-Elements des <code>RPortPrototype</code>.</li>\n</ul>\n<p class=\"fig-p\">Damit wird festgelegt, wie einzelne Bits beim Lese-/Schreibzugriff über Ports in das Bitfeld des NVRAM-Spiegels extrahiert bzw. eingefügt werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevanter Modellierungsmechanismus für die ressourceneffiziente Speicherung mehrerer boolescher oder kleiner Zustandswerte in einem gemeinsamen NV-RAM-Block. Bei der Konfiguration eines <code>NvBlockSwComponentType</code> müssen die Bitmasken (<code>bitfieldTextTableMaskNvBlockDescriptor</code> und <code>bitfieldTextTableMaskPortPrototype</code>) kollisionsfrei und passend zu den Datentypen der Port-Interfaces definiert werden, um fehlerhafte Bit-Überlagerungen im RAM-Spiegel zu vermeiden.</p>"}, {"id": "FIG-410f304341df75d8", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Mapping- und Strukturdiagramm der AUTOSAR Classic Platform (Software Component Template). Das Schaubild visualisiert das Bitfield-Mapping innerhalb eines <code>NvBlockSwComponentType</code> zwischen einzelnen Bits eines nichtflüchtigen Speicherblocks (<code>NvBlockDescriptor.ramBlock</code>) und den Datenelementen eines Ports (<code>RPortPrototype</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Hauptentitäten:</p>\n<ul class=\"fig-list\">\n<li><strong>NvBlockDescriptor</strong>: Repräsentiert den NV-Block und enthält <code>NvBlockDescriptor.ramBlock</code> als Byte- bzw. Bitfeldstruktur mit 8 visualisierten Bit-Positionen, von denen Bit 1 (Maske 0x02) und Bit 4 (Maske 0x10) blau hervorgehoben sind.</li>\n<li><strong>RPortPrototype</strong>: Repräsentiert die Port-Schnittstelle mit zwei separaten Datenelementen vom Typ <code>Boolean</code>, bei denen jeweils das niederwertigste Bit (LSB) hervorgehoben ist.</li>\n<li><strong>NvBlockDataMapping</strong>: Zwei Mapping-Instanzen mit folgenden Attributbelegungen:</li>\n<li>Erstes Mapping: <code>bitfieldTextTableMaskNvBlockDescriptor = 0x10</code>, <code>bitfieldTextTableMaskPortPrototype = 0x01</code> (verbindet Bit 4 des RAM-Blocks mit dem zweiten Boolean-Datenelement).</li>\n<li>Zweites Mapping: <code>bitfieldTextTableMaskNvBlockDescriptor = 0x02</code>, <code>bitfieldTextTableMaskPortPrototype = 0x01</code> (verbindet Bit 1 des RAM-Blocks mit dem ersten Boolean-Datenelement).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Abbildungsmodell ohne sequenziellen Laufzeitablauf. Gerichtete Pfeile definieren die Zuordnungsvorschrift:</p>\n<ul class=\"fig-list\">\n<li>Der Pfeil von der oberen <code>NvBlockDataMapping</code>-Instanz zeigt auf Bit 1 des <code>ramBlock</code> sowie auf das LSB des oberen <code>Boolean</code>-Elements des <code>RPortPrototype</code>.</li>\n<li>Der Pfeil von der unteren <code>NvBlockDataMapping</code>-Instanz zeigt auf Bit 4 des <code>ramBlock</code> sowie auf das LSB des unteren <code>Boolean</code>-Elements des <code>RPortPrototype</code>.</li>\n</ul>\n<p class=\"fig-p\">Damit wird festgelegt, wie einzelne Bits beim Lese-/Schreibzugriff über Ports in das Bitfeld des NVRAM-Spiegels extrahiert bzw. eingefügt werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevanter Modellierungsmechanismus für die ressourceneffiziente Speicherung mehrerer boolescher oder kleiner Zustandswerte in einem gemeinsamen NV-RAM-Block. Bei der Konfiguration eines <code>NvBlockSwComponentType</code> müssen die Bitmasken (<code>bitfieldTextTableMaskNvBlockDescriptor</code> und <code>bitfieldTextTableMaskPortPrototype</code>) kollisionsfrei und passend zu den Datentypen der Port-Interfaces definiert werden, um fehlerhafte Bit-Überlagerungen im RAM-Spiegel zu vermeiden.</p>"}], "trans": [{"from": "FIG-ae1931a6a16797e5", "to": "FIG-410f304341df75d8", "fr": "R19-11", "tr": "R20-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>NvBlockDataMapping</strong>: Die beiden Mapping-Elemente sind nun nebeneinander auf gleicher horizontaler Ebene angeordnet (zuvor vertikal versetzt/untereinander), mit entsprechend angepasster Pfeilführung zu <code>NvBlockDescriptor.ramBlock</code> und <code>RPortPrototype</code>.</li>\n<li><strong>Bildformat / Layout</strong>: Das Diagrammlayout wurde von Hochformat auf Querformat umgestellt.</li>\n</ul>"}]};
